"""Tests for STORY-01-05: module-level ``append`` in ledgerlock.ledger (R-13/2),
plus the preserved stdlib-only (R-10/1) and no-side-channel (R-12/1) contracts.
"""

from __future__ import annotations

import ast
import inspect
import json
import tempfile
import unittest
from pathlib import Path

import ledgerlock.ledger as ledger_mod
from ledgerlock import ConflictError, Ledger
from ledgerlock.ledger import append

REPO_ROOT = Path(__file__).resolve().parent.parent
PKG_DIR = REPO_ROOT / "ledgerlock"

ALLOWED_MODULES = {
    "hashlib",
    "json",
    "os",
    "sys",
    "pathlib",
    "tempfile",
    "argparse",
    "unittest",
    "typing",
    "unicodedata",
    "uuid",
}

FORBIDDEN_TOKENS = (
    "socket",
    "subprocess",
    "os.system",
)


def _package_files():
    return sorted(PKG_DIR.glob("*.py"))


def _collect_imported_modules(path):
    tree = ast.parse(path.read_text(encoding="utf-8"))
    mods = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                mods.add(a.name.split(".")[0])
        elif isinstance(node, ast.ImportFrom):
            if node.level > 0:
                continue
            if node.module:
                mods.add(node.module.split(".")[0])
    return mods


class TestLedgerPyExposesAppend(unittest.TestCase):
    """R-13/2: ledger.py must define Ledger, ConflictError, append,
    verify, snapshot, apply_batch."""

    def test_ledger_and_conflict_error_are_module_level(self):
        self.assertIs(ledger_mod.Ledger, Ledger)
        self.assertIs(ledger_mod.ConflictError, ConflictError)

    def test_append_is_module_level_symbol(self):
        self.assertTrue(hasattr(ledger_mod, "append"))
        self.assertTrue(callable(ledger_mod.append))

    def test_append_is_a_function(self):
        self.assertTrue(inspect.isfunction(ledger_mod.append))

    def test_append_importable_directly(self):
        self.assertTrue(callable(append))

    def test_ledger_methods_still_present(self):
        for meth in ("append", "verify", "snapshot", "apply_batch"):
            self.assertTrue(hasattr(Ledger, meth), f"Ledger.{meth} missing")


class TestModuleLevelAppend(unittest.TestCase):
    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.path = Path(self._tmp.name) / "ledger.jsonl"

    def tearDown(self):
        self._tmp.cleanup()

    def test_append_returns_hash_and_commits(self):
        h = append(self.path, "put", "a", 1, "r1", 1)
        self.assertIsInstance(h, str)
        self.assertEqual(len(h), 64)
        self.assertTrue(Ledger(self.path).verify()["ok"])
        self.assertEqual(Ledger(self.path).snapshot(), {"a": 1})

    def test_append_conflict_raises(self):
        append(self.path, "put", "a", 1, "r1", 1)
        with self.assertRaises(ConflictError):
            append(self.path, "put", "a", 2, "r2", 2)

    def test_append_idempotent_replay(self):
        h1 = append(self.path, "put", "a", 1, "r1", 1)
        h2 = append(self.path, "put", "a", 1, "r1", 1)
        self.assertEqual(h1, h2)
        self.assertEqual(self.path.read_bytes().count(b"\n"), 1)

    def test_append_delete_tombstone(self):
        append(self.path, "delete", "a", None, "r1", 1)
        self.assertEqual(Ledger(self.path).snapshot(), {})


class TestStdlibOnly(unittest.TestCase):
    """R-10/1: the package imports only the allowed standard-library modules."""

    def test_package_imports_are_allowed(self):
        for p in _package_files():
            mods = _collect_imported_modules(p)
            offending = {
                m
                for m in mods
                if m not in ALLOWED_MODULES
                and not m.startswith("ledgerlock")
                and m != "__future__"
            }
            self.assertEqual(
                set(),
                offending,
                f"{p.name} imports non-allowed modules: {sorted(offending)}",
            )

    def test_future_annotations_present(self):
        for p in _package_files():
            self.assertIn(
                "from __future__ import annotations",
                p.read_text(encoding="utf-8"),
                f"{p.name} missing 'from __future__ import annotations'",
            )


class TestNoSideChannels(unittest.TestCase):
    """R-12/1: no socket, no subprocess, no os.system anywhere in the package."""

    def test_forbidden_tokens_absent(self):
        for p in _package_files():
            src = p.read_text(encoding="utf-8")
            for tok in FORBIDDEN_TOKENS:
                self.assertNotIn(tok, src, f"{p.name} contains forbidden token {tok!r}")


if __name__ == "__main__":
    unittest.main()
